tasks.starter:
let clock = 0;
const entry = { data: 'v1', ts: 0 };
const TTL = 10;
let refetches = 0;
function revalidate() { refetches++; return 'v2@t' + clock; }
// BUG: serves stale but never revalidates — the refresh line is unreachable
function read() {
  if (clock - entry.ts < TTL) return entry.data;
  const out = entry.data;
  return out;
  entry.data = revalidate(); entry.ts = clock;
}

tasks.verify:
clock = 15;
const first = read();
if (first !== 'v1') throw new Error('must serve stale immediately, got ' + first);
if (refetches !== 1) throw new Error('must trigger exactly one revalidation, got ' + refetches);
const second = read();
if (second !== 'v2@t15') throw new Error('second read must be fresh, got ' + second);
if (refetches !== 1) throw new Error('must not revalidate twice, got ' + refetches);
